const fs = require('node:fs');
if (process.argv[2] === 'cleanup') {
  fs.rmSync('service.log', { force: true });
  process.stdout.write('service.log removed\n');
} else {
  const noise = '2026-09-05T00:00:00Z INFO request completed status=200\n'.repeat(90000);
  const marker = '2026-09-05T00:01:00Z ERROR checkout failed correlation=order-needle-42\n';
  const content = noise + marker;
  fs.writeFileSync('service.log', content);
  process.stdout.write(content);
}

import assert from 'node:assert/strict';
import { existsSync } from 'node:fs';
import test from 'node:test';
test('temporary diagnostic log was cleaned', () => assert.equal(existsSync('service.log'), false));
